B.Bt=s(["    CREATE TABLE IF NOT EXISTS skill_scenarios (\n      owner_id TEXT NOT NULL,\n      id TEXT NOT NULL,\n      scenario_json TEXT NOT NULL,\n      PRIMARY KEY (owner_id, id),\n      FOREIGN KEY (owner_id) REFERENCES workspaces(owner_id) ON DELETE CASCADE\n    );\n    ","    CREATE TABLE IF NOT EXISTS account_snapshots (\n      owner_id TEXT PRIMARY KEY,\n      snapshot_json TEXT NOT NULL,\n      FOREIGN KEY (owner_id) REFERENCES workspaces(owner_id) ON DELETE CASCADE\n    );\n    ","    CREATE TABLE IF NOT EXISTS workspaces (\n      owner_id TEXT PRIMARY KEY,\n      installation_id TEXT NOT NULL,\n      schema_version INTEGER NOT NULL,\n      workspace_epoch INTEGER NOT NULL,\n      created_at_utc TEXT NOT NULL,\n      updated_at_utc TEXT NOT NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS teacher_preferences (\n      owner_id TEXT PRIMARY KEY,\n      subject TEXT NOT NULL,\n      custom_subject TEXT,\n      grades_json TEXT NOT NULL,\n      ui_language TEXT NOT NULL,\n      assistant_language TEXT NOT NULL,\n      reminders_enabled INTEGER NOT NULL DEFAULT 0,\n      storage_retention_days INTEGER,\n      updated_at_utc TEXT NOT NULL,\n      FOREIGN KEY (owner_id) REFERENCES workspaces(owner_id) ON DELETE CASCADE\n    );\n    ","    CREATE TABLE IF NOT EXISTS assistant_configurations (\n      owner_id TEXT PRIMARY KEY,\n      name TEXT NOT NULL,\n      selected_category TEXT,\n      enabled_skills_json TEXT NOT NULL,\n      system_rules_json TEXT NOT NULL,\n      state_revision INTEGER NOT NULL DEFAULT 1,\n      updated_at_utc TEXT NOT NULL,\n      FOREIGN KEY (owner_id) REFERENCES workspaces(owner_id) ON DELETE CASCADE\n    );\n    ","    CREATE TABLE IF NOT EXISTS instruction_rules (\n      id TEXT PRIMARY KEY,\n      owner_id TEXT NOT NULL,\n      group_name TEXT NOT NULL,\n      rule_text TEXT NOT NULL,\n      is_enabled INTEGER NOT NULL,\n      sort_order INTEGER NOT NULL,\n      source TEXT NOT NULL,\n      revision INTEGER NOT NULL,\n      updated_at_utc TEXT NOT NULL,\n      FOREIGN KEY (owner_id) REFERENCES workspaces(owner_id) ON DELETE CASCADE\n    );\n    ","    CREATE TABLE IF NOT EXISTS assistant_versions (\n      owner_id TEXT NOT NULL,\n      version_number INTEGER NOT NULL,\n      created_at_utc TEXT NOT NULL,\n      reason TEXT NOT NULL,\n      parent_id TEXT,\n      schema_version INTEGER NOT NULL,\n      snapshot_json TEXT NOT NULL,\n      PRIMARY KEY(owner_id, version_number),\n      FOREIGN KEY (owner_id) REFERENCES workspaces(owner_id) ON DELETE CASCADE\n    );\n    ","    CREATE TABLE IF NOT EXISTS conversations (\n      id TEXT PRIMARY KEY,\n      owner_id TEXT NOT NULL,\n      title TEXT NOT NULL,\n      created_at_utc TEXT NOT NULL,\n      activity_at_utc TEXT NOT NULL,\n      retention_policy TEXT NOT NULL,\n      FOREIGN KEY (owner_id) REFERENCES workspaces(owner_id) ON DELETE CASCADE\n    );\n    ","    CREATE TABLE IF NOT EXISTS messages (\n      id TEXT PRIMARY KEY,\n      conversation_id TEXT NOT NULL,\n      owner_id TEXT NOT NULL,\n      role TEXT NOT NULL,\n      content TEXT NOT NULL,\n      status TEXT NOT NULL,\n      request_id TEXT,\n      assistant_version INTEGER,\n      created_at_utc TEXT NOT NULL,\n      FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,\n      FOREIGN KEY (owner_id) REFERENCES workspaces(owner_id) ON DELETE CASCADE\n    );\n    ","    CREATE TABLE IF NOT EXISTS request_traces (\n      request_id TEXT PRIMARY KEY,\n      owner_id TEXT NOT NULL,\n      context_layers_json TEXT NOT NULL,\n      sent_chunks_json TEXT NOT NULL,\n      usage_json TEXT NOT NULL,\n      duration_ms INTEGER NOT NULL,\n      error_code TEXT,\n      created_at_utc TEXT NOT NULL,\n      FOREIGN KEY (owner_id) REFERENCES workspaces(owner_id) ON DELETE CASCADE\n    );\n    ","    CREATE TABLE IF NOT EXISTS knowledge_documents (\n      id TEXT PRIMARY KEY,\n      owner_id TEXT NOT NULL,\n      content_hash TEXT NOT NULL,\n      file_name TEXT NOT NULL,\n      file_format TEXT NOT NULL,\n      file_size_bytes INTEGER NOT NULL,\n      is_enabled INTEGER NOT NULL,\n      index_status TEXT NOT NULL,\n      created_at_utc TEXT NOT NULL,\n      FOREIGN KEY (owner_id) REFERENCES workspaces(owner_id) ON DELETE CASCADE\n    );\n    ","    CREATE TABLE IF NOT EXISTS document_revisions (\n      id TEXT PRIMARY KEY,\n      document_id TEXT NOT NULL,\n      owner_id TEXT NOT NULL,\n      parser_version TEXT NOT NULL,\n      embedding_model_id TEXT,\n      text_content TEXT NOT NULL,\n      blob_path TEXT,\n      created_at_utc TEXT NOT NULL,\n      FOREIGN KEY (document_id) REFERENCES knowledge_documents(id) ON DELETE CASCADE,\n      FOREIGN KEY (owner_id) REFERENCES workspaces(owner_id) ON DELETE CASCADE\n    );\n    ","    CREATE TABLE IF NOT EXISTS knowledge_chunks (\n      id TEXT PRIMARY KEY,\n      revision_id TEXT NOT NULL,\n      owner_id TEXT NOT NULL,\n      chunk_index INTEGER NOT NULL,\n      chunk_text TEXT NOT NULL,\n      page_number INTEGER,\n      byte_offset INTEGER,\n      embedding_metadata_json TEXT,\n      FOREIGN KEY (revision_id) REFERENCES document_revisions(id) ON DELETE CASCADE,\n      FOREIGN KEY (owner_id) REFERENCES workspaces(owner_id) ON DELETE CASCADE\n    );\n    ","    CREATE TABLE IF NOT EXISTS memory_facts (\n      id TEXT PRIMARY KEY,\n      owner_id TEXT NOT NULL,\n      fact_text TEXT NOT NULL,\n      source TEXT NOT NULL,\n      is_enabled INTEGER NOT NULL,\n      created_at_utc TEXT NOT NULL,\n      updated_at_utc TEXT NOT NULL,\n      FOREIGN KEY (owner_id) REFERENCES workspaces(owner_id) ON DELETE CASCADE\n    );\n    ","    CREATE TABLE IF NOT EXISTS tool_grants (\n      owner_id TEXT NOT NULL,\n      tool_name TEXT NOT NULL,\n      is_enabled INTEGER NOT NULL,\n      permission_scope TEXT NOT NULL,\n      revision INTEGER NOT NULL,\n      updated_at_utc TEXT NOT NULL,\n      PRIMARY KEY (owner_id, tool_name),\n      FOREIGN KEY (owner_id) REFERENCES workspaces(owner_id) ON DELETE CASCADE\n    );\n    ","    CREATE TABLE IF NOT EXISTS pending_actions (\n      invocation_id TEXT PRIMARY KEY,\n      owner_id TEXT NOT NULL,\n      workspace_epoch INTEGER NOT NULL,\n      action_name TEXT NOT NULL,\n      params_hash TEXT NOT NULL,\n      params_json TEXT NOT NULL,\n      status TEXT NOT NULL,\n      expires_at_utc TEXT,\n      created_at_utc TEXT NOT NULL,\n      FOREIGN KEY (owner_id) REFERENCES workspaces(owner_id) ON DELETE CASCADE\n    );\n    ","    CREATE TABLE IF NOT EXISTS tool_invocations (\n      id TEXT PRIMARY KEY,\n      owner_id TEXT NOT NULL,\n      tool_name TEXT NOT NULL,\n      invocation_source TEXT NOT NULL,\n      args_json TEXT NOT NULL,\n      result_json TEXT,\n      started_at_utc TEXT NOT NULL,\n      completed_at_utc TEXT,\n      execution_id TEXT,\n      FOREIGN KEY (owner_id) REFERENCES workspaces(owner_id) ON DELETE CASCADE\n    );\n    ","    CREATE TABLE IF NOT EXISTS course_progress (\n      owner_id TEXT NOT NULL,\n      level_id TEXT NOT NULL,\n      content_version TEXT NOT NULL,\n      current_step INTEGER NOT NULL,\n      completed_checkpoints_json TEXT NOT NULL,\n      attempts_count INTEGER NOT NULL,\n      is_completed INTEGER NOT NULL,\n      updated_at_utc TEXT NOT NULL,\n      PRIMARY KEY (owner_id, level_id),\n      FOREIGN KEY (owner_id) REFERENCES workspaces(owner_id) ON DELETE CASCADE\n    );\n    ","    CREATE TABLE IF NOT EXISTS quiz_attempts (\n      id TEXT PRIMARY KEY,\n      owner_id TEXT NOT NULL,\n      level_id TEXT NOT NULL,\n      question_revisions_json TEXT NOT NULL,\n      answers_json TEXT NOT NULL,\n      score REAL NOT NULL,\n      threshold REAL NOT NULL,\n      completed_at_utc TEXT NOT NULL,\n      FOREIGN KEY (owner_id) REFERENCES workspaces(owner_id) ON DELETE CASCADE\n    );\n    ","    CREATE TABLE IF NOT EXISTS file_staging_journal (\n      id TEXT PRIMARY KEY,\n      owner_id TEXT NOT NULL,\n      staging_path TEXT NOT NULL,\n      target_path TEXT NOT NULL,\n      status TEXT NOT NULL,\n      created_at_utc TEXT NOT NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS policy_acknowledgments (\n      owner_id TEXT NOT NULL,\n      policy_id TEXT NOT NULL,\n      policy_version TEXT NOT NULL,\n      acknowledged_at_utc TEXT NOT NULL,\n      PRIMARY KEY (owner_id, policy_id)\n    );\n    ","CREATE INDEX IF NOT EXISTS idx_messages_conv ON messages(conversation_id, created_at_utc);","CREATE INDEX IF NOT EXISTS idx_traces_owner ON request_traces(owner_id, created_at_utc);","CREATE INDEX IF NOT EXISTS idx_docs_owner ON knowledge_documents(owner_id);","CREATE INDEX IF NOT EXISTS idx_chunks_rev ON knowledge_chunks(revision_id);","CREATE INDEX IF NOT EXISTS idx_facts_owner ON memory_facts(owner_id, is_enabled);","CREATE INDEX IF NOT EXISTS idx_staging_status ON file_staging_journal(status);"],t.s)
