B.al5=new A.iQ("les_1","\u041a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u044b\u0435 \u0443\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f: \u0442\u0435\u043e\u0440\u0435\u043c\u0430 \u0412\u0438\u0435\u0442\u0430","\u0410\u043b\u0433\u0435\u0431\u0440\u0430",8,"\u0422\u0435\u043e\u0440\u0435\u043c\u0430 \u0412\u0438\u0435\u0442\u0430 \u0438 \u0435\u0451 \u043f\u0440\u0438\u043c\u0435\u043d\u0435\u043d\u0438\u0435 \u043a \u043f\u0440\u0438\u0432\u0435\u0434\u0435\u043d\u043d\u044b\u043c \u043a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u044b\u043c \u0443\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f\u043c","\u0421\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u0443\u0440\u043e\u043a\u0430: \u0430\u043a\u0442\u0443\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0444\u043e\u0440\u043c\u0443\u043b\u044b \u043a\u043e\u0440\u043d\u0435\u0439, \u0432\u044b\u0432\u043e\u0434 \u0441\u043e\u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0439 \u043c\u0435\u0436\u0434\u0443 \u043a\u043e\u0440\u043d\u044f\u043c\u0438 \u0438 \u043a\u043e\u044d\u0444\u0444\u0438\u0446\u0438\u0435\u043d\u0442\u0430\u043c\u0438, \u043f\u043e\u0434\u0431\u043e\u0440 \u043a\u043e\u0440\u043d\u0435\u0439 \u0446\u0435\u043b\u044b\u0445 \u0443\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0439.","\u0426\u0435\u043b\u044c \u0443\u0440\u043e\u043a\u0430:\n1. \u0421\u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0438 \u0434\u043e\u043a\u0430\u0437\u0430\u0442\u044c \u043f\u0440\u044f\u043c\u0443\u044e \u0438 \u043e\u0431\u0440\u0430\u0442\u043d\u0443\u044e \u0442\u0435\u043e\u0440\u0435\u043c\u0443 \u0412\u0438\u0435\u0442\u0430.\n2. \u041d\u0430\u0443\u0447\u0438\u0442\u044c \u0443\u0447\u0430\u0449\u0438\u0445\u0441\u044f \u043d\u0430\u0445\u043e\u0434\u0438\u0442\u044c \u0441\u0443\u043c\u043c\u0443 \u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u0435\u0434\u0435\u043d\u0438\u0435 \u043a\u043e\u0440\u043d\u0435\u0439 \u0431\u0435\u0437 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0434\u0438\u0441\u043a\u0440\u0438\u043c\u0438\u043d\u0430\u043d\u0442\u0430.\n\n\u041f\u043b\u0430\u043d \u0443\u0440\u043e\u043a\u0430 (40 \u043c\u0438\u043d\u0443\u0442):\n\u2022 0-5 \u043c\u0438\u043d: \u041e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u043c\u043e\u043c\u0435\u043d\u0442, \u0443\u0441\u0442\u043d\u044b\u0439 \u0441\u0447\u0451\u0442.\n\u2022 5-15 \u043c\u0438\u043d: \u0418\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u0441\u043a\u0430\u044f \u0440\u0430\u0431\u043e\u0442\u0430: \u0442\u0430\u0431\u043b\u0438\u0446\u0430 \u043a\u043e\u0440\u043d\u0435\u0439 \u0438 \u043a\u043e\u044d\u0444\u0444\u0438\u0446\u0438\u0435\u043d\u0442\u043e\u0432 x\xb2 + px + q = 0.\n\u2022 15-25 \u043c\u0438\u043d: \u0424\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u043a\u0430 \u0442\u0435\u043e\u0440\u0435\u043c\u044b x\u2081 + x\u2082 = -p, x\u2081 \xb7 x\u2082 = q.\n\u2022 25-35 \u043c\u0438\u043d: \u041f\u0440\u0430\u043a\u0442\u0438\u043a\u0443\u043c: \u0440\u0435\u0448\u0435\u043d\u0438\u0435 4 \u0443\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0439 \u0443\u0441\u0442\u043d\u044b\u043c \u043f\u043e\u0434\u0431\u043e\u0440\u043e\u043c \u043a\u043e\u0440\u043d\u0435\u0439.\n\u2022 35-40 \u043c\u0438\u043d: \u0420\u0435\u0444\u043b\u0435\u043a\u0441\u0438\u044f \u0438 \u0434\u0438\u0444\u0444\u0435\u0440\u0435\u043d\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0435 \u0434\u043e\u043c\u0430\u0448\u043d\u0435\u0435 \u0437\u0430\u0434\u0430\u043d\u0438\u0435.","\u041c\u0435\u0442\u043e\u0434\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0441\u043e\u0432\u0435\u0442 \u0443\u0447\u0438\u0442\u0435\u043b\u0435\u0439 \u043c\u0430\u0442\u0435\u043c\u0430\u0442\u0438\u043a\u0438")
B.al6=new A.iQ("les_2","\u0417\u0430\u043a\u043e\u043d\u044b \u041d\u044c\u044e\u0442\u043e\u043d\u0430: \u0432\u0442\u043e\u0440\u043e\u0439 \u0437\u0430\u043a\u043e\u043d \u0434\u0438\u043d\u0430\u043c\u0438\u043a\u0438","\u0424\u0438\u0437\u0438\u043a\u0430",9,"\u0412\u0437\u0430\u0438\u043c\u043e\u0441\u0432\u044f\u0437\u044c \u043c\u0435\u0436\u0434\u0443 \u0441\u0438\u043b\u043e\u0439, \u043c\u0430\u0441\u0441\u043e\u0439 \u0438 \u0443\u0441\u043a\u043e\u0440\u0435\u043d\u0438\u0435\u043c \u0442\u0435\u043b\u0430 (F = ma)","\u041f\u043b\u0430\u043d \u043b\u0430\u0431\u043e\u0440\u0430\u0442\u043e\u0440\u043d\u043e\u0433\u043e \u0434\u0435\u043c\u043e\u043d\u0441\u0442\u0440\u0430\u0446\u0438\u043e\u043d\u043d\u043e\u0433\u043e \u0443\u0440\u043e\u043a\u0430 \u0441 \u0442\u0435\u043b\u0435\u0436\u043a\u043e\u0439 \u0438 \u0433\u0440\u0443\u0437\u0430\u043c\u0438, \u0433\u0440\u0430\u0444\u0438\u043a \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438 a(F).","\u0426\u0435\u043b\u044c \u0443\u0440\u043e\u043a\u0430:\n\u042d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430\u043b\u044c\u043d\u043e \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u044c \u0443\u0441\u043a\u043e\u0440\u0435\u043d\u0438\u044f \u0442\u0435\u043b\u0430 \u043e\u0442 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u043d\u043e\u0439 \u0441\u0438\u043b\u044b \u043f\u0440\u0438 \u043f\u043e\u0441\u0442\u043e\u044f\u043d\u043d\u043e\u0439 \u043c\u0430\u0441\u0441\u0435.\n\n\u041e\u0431\u043e\u0440\u0443\u0434\u043e\u0432\u0430\u043d\u0438\u0435:\n\u0414\u0438\u043d\u0430\u043c\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0442\u0435\u043b\u0435\u0436\u043a\u0430, \u043d\u0430\u0431\u043e\u0440 \u0433\u0440\u0443\u0437\u043e\u0432, \u0441\u0435\u043a\u0443\u043d\u0434\u043e\u043c\u0435\u0440, \u043d\u0430\u043a\u043b\u043e\u043d\u043d\u0430\u044f \u043f\u043b\u043e\u0441\u043a\u043e\u0441\u0442\u044c.\n\n\u0425\u043e\u0434 \u0437\u0430\u043d\u044f\u0442\u0438\u044f:\n1. \u0410\u043a\u0442\u0443\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u043f\u043e\u043d\u044f\u0442\u0438\u044f \u0438\u043d\u0435\u0440\u0446\u0438\u0438 (1-\u0439 \u0437\u0430\u043a\u043e\u043d).\n2. \u0414\u0435\u043c\u043e\u043d\u0441\u0442\u0440\u0430\u0446\u0438\u044f \u043e\u043f\u044b\u0442\u0430: \u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u0435 \u0441\u0438\u043b\u044b \u0442\u044f\u0433\u0438 \u0432 2 \u0440\u0430\u0437\u0430 \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0432\u0430\u0435\u0442 \u0443\u0441\u043a\u043e\u0440\u0435\u043d\u0438\u0435 \u0442\u0435\u043b\u0435\u0436\u043a\u0438 \u0432 2 \u0440\u0430\u0437\u0430.\n3. \u0412\u044b\u0432\u043e\u0434 \u0444\u043e\u0440\u043c\u0443\u043b\u044b F = ma \u0438 \u0435\u0434\u0438\u043d\u0438\u0446\u044b \u0441\u0438\u043b\u044b 1 \u041d\u044c\u044e\u0442\u043e\u043d (\u041d).\n4. \u0420\u0435\u0448\u0435\u043d\u0438\u0435 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u0438 \u0440\u0430\u0441\u0447\u0451\u0442\u043d\u044b\u0445 \u0437\u0430\u0434\u0430\u0447 (\u0442\u043e\u0440\u043c\u043e\u0437\u043d\u043e\u0439 \u043f\u0443\u0442\u044c \u0430\u0432\u0442\u043e\u043c\u043e\u0431\u0438\u043b\u044f).","\u0410\u0441\u0441\u043e\u0446\u0438\u0430\u0446\u0438\u044f \u0443\u0447\u0438\u0442\u0435\u043b\u0435\u0439 \u0444\u0438\u0437\u0438\u043a\u0438")
